Running command: cd /workspace && bash build.sh 'cd /gt/_work/src && printf "#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int main(int argc, char** argv) {
    if(argc < 2) { fprintf(stderr, "usage: %%s <input_file>\n", argv[0]); return 1; }
    FILE* f = fopen(argv[1], "rb");
    if(!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* buf = malloc(sz);
    if(fread(buf, 1, sz, f) != (size_t)sz) { perror("fread"); return 1; }
    fclose(f);
    LLVMFuzzerTestOneInput(buf, sz);
    free(buf);
    return 0;
}
" > /tmp/test_driver.c && gcc -fsanitize=address -g -O1 -I src /tmp/test_driver.c test/fuzzers/fuzz-mdhtml.c src/md4c.c src/md4c-html.c src/entity.c -o /tmp/fuzz-mdhtml 2>&1 && echo BUILD_OK'

